import sys,csv,argparse,re,os

def read_rows(path=None, delim=','):
    f=open(path,newline='') if path and path!='-' else sys.stdin
    try: return list(csv.reader(f,delimiter=delim))
    finally:
        if f is not sys.stdin:f.close()
def emit(rows, delim=',', out=None, crlf=False, quote=csv.QUOTE_MINIMAL):
    f=open(out,'w',newline='') if out else sys.stdout
    w=csv.writer(f,delimiter=delim,lineterminator='\r\n' if crlf else '\n',quoting=quote)
    w.writerows(rows)
    if out:f.close()
def patharg(a): return a[-1] if a else None
def main_core(cmd,argv):
    # returns whether handled
    if cmd=='count':
